<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class EstadoCuenta extends Model {protected $table='estados_cuenta';public $timestamps=false;protected $fillable=['inmueble_id','periodo_mes','periodo_anio','cuota_ordinaria','cuota_extraordinaria','intereses_mora','sanciones','descuentos','pagos_realizados','saldo_pendiente','fecha_vencimiento','creado_en'];protected $casts=['fecha_vencimiento'=>'date','creado_en'=>'datetime'];}
class ExtractoBancario extends Model {protected $table='extractos_bancarios';public $timestamps=false;protected $fillable=['fecha_importacion','importado_por','nombre_archivo','total_registros'];protected $casts=['fecha_importacion'=>'datetime'];}
class MovimientoBancario extends Model {protected $table='movimientos_bancarios';public $timestamps=false;protected $fillable=['extracto_id','fecha_movimiento','descripcion','referencia','valor','tipo_movimiento_id','canal_pago_id','estado_conciliacion_id'];protected $casts=['fecha_movimiento'=>'date','valor'=>'decimal:2'];}
class Pago extends Model {protected $table='pagos';public $timestamps=false;protected $fillable=['inmueble_id','movimiento_bancario_id','fecha_pago','valor_transferido','medio_pago_id','banco_origen','soporte_url','observaciones','registrado_por','creado_en'];protected $casts=['fecha_pago'=>'datetime','valor_transferido'=>'decimal:2','creado_en'=>'datetime'];}
class SugerenciaConciliacion extends Model {protected $table='sugerencias_conciliacion';public $timestamps=false;protected $fillable=['movimiento_id','inmueble_id','puntaje_confianza','criterios_coincidencia','creado_en'];protected $casts=['criterios_coincidencia'=>'array','creado_en'=>'datetime'];}
